def balanced(s):
    inside_quote = None
    escape = False
    stack = []
    for c in s:
        if escape:
            escape = False
            continue
        if inside_quote is not None:
            if c == '\\':
                escape = True
            elif c == inside_quote:
                inside_quote = None
            # else: normal char, do nothing
        else:
            if c in ('"', "'"):
                inside_quote = c
            elif c in '([{':
                stack.append(c)
            elif c in ')]}':
                if not stack:
                    return False
                top = stack.pop()
                if (top == '(' and c != ')') or (top == '[' and c != ']') or (top == '{' and c != '}'):
                    return False
    if inside_quote is not None:
        return False
    return len(stack) == 0

